def top_k_counts(words: list[str], k: int) -> list[tuple[str, int]]:
    if k <= 0:
        return []

    first_word = {}
    first_index = {}
    counts = {}

    for i, word in enumerate(words):
        lower = word.lower()
        if lower not in counts:
            counts[lower] = 0
            first_word[lower] = word
            first_index[lower] = i
        counts[lower] += 1

    sorted_keys = sorted(counts.keys(), key=lambda w: (-counts[w], first_index[w]))

    return [(first_word[w], counts[w]) for w in sorted_keys[:k]]
