def merge_intervals(intervals):
    if not all(isinstance(interval, (list, tuple)) and len(interval) == 2 for interval in intervals):
        raise ValueError("Each interval must be a list or tuple of length 2")

    for start, end in intervals:
        if start > end:
            raise ValueError(f"Interval {start, end} has start > end")

    sorted_intervals = sorted(intervals, key=lambda x: x[0])
    if not sorted_intervals:
        return []

    merged = [list(sorted_intervals[0])]
    for start, end in sorted_intervals[1:]:
        current = merged[-1]
        if start <= current[1]:
            current[1] = max(current[1], end)
        else:
            merged.append([start, end])

    return [tuple(interval) for interval in merged]
