import json
import math
from collections import defaultdict


def parse_jsonl_metrics(lines: list[str]) -> dict:
    invalid = 0
    groups = defaultdict(list)  # service -> list of (latency_ms, is_ok)

    for raw in lines:
        line = raw.strip()
        if not line:
            continue
        try:
            rec = json.loads(line)
        except (ValueError, TypeError):
            invalid += 1
            continue
        if not isinstance(rec, dict):
            invalid += 1
            continue
        service = rec.get("service")
        latency = rec.get("latency_ms")
        status = rec.get("status")
        if not isinstance(service, str):
            invalid += 1
            continue
        if not isinstance(latency, (int, float)) or isinstance(latency, bool):
            invalid += 1
            continue
        if not isinstance(status, (int, float)) or isinstance(status, bool):
            invalid += 1
            continue
        is_ok = 200 <= status < 300
        groups[service].append((latency, is_ok))

    result = {"invalid": invalid}
    services = sorted(groups.keys())
    for svc in services:
        samples = sorted(lat for lat, _ in groups[svc])
        n = len(samples)
        ok_count = sum(1 for _, ok in groups[svc] if ok)
        ok_rate = ok_count / n
        if n == 0:
            p95 = None
        else:
            idx = max(0, math.ceil(0.95 * n) - 1)
            if idx >= n:
                idx = n - 1
            p95 = samples[idx]
        result[svc] = {"count": n, "ok_rate": ok_rate, "p95_latency_ms": p95}
    return result
