import threading
from collections import deque


class BoundedQueue:
    def __init__(self, capacity):
        self._q = deque()
        self._cap = capacity
        self._closed = False
        self._cond = threading.Condition()

    def put(self, item):
        with self._cond:
            while len(self._q) >= self._cap and not self._closed:
                self._cond.wait()
            if self._closed:
                raise ClosedError("put to a closed queue")
            self._q.append(item)
            self._cond.notify()

    def get(self):
        with self._cond:
            while len(self._q) == 0 and not self._closed:
                self._cond.wait()
            if len(self._q) == 0:
                raise ClosedError("get from a closed and empty queue")
            item = self._q.popleft()
            self._cond.notify()
            return item

    def close(self):
        with self._cond:
            self._closed = True
            self._cond.notify_all()


class ClosedError(Exception):
    pass
